import{_ as a,a as n,c as e,b as l}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"02-文章大纲与目录组件","description":"深入剖析右侧文章目录 PostToc 组件的三级大纲抓取、视口滚动高亮追踪、平滑锚点定位与阅读进度联动。","frontmatter":{"title":"02-文章大纲与目录组件","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"深入剖析右侧文章目录 PostToc 组件的三级大纲抓取、视口滚动高亮追踪、平滑锚点定位与阅读进度联动。","tags":["组件设计","文章大纲"]},"headers":[],"relativePath":"posts/0-博客指南/博客的组件设计/02-文章大纲与目录组件.md","filePath":"posts/0-博客指南/博客的组件设计/02-文章大纲与目录组件.md"}'),t={name:"posts/0-博客指南/博客的组件设计/02-文章大纲与目录组件.md"};function o(i,s,r,p,c,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_02-文章大纲与目录组件" tabindex="-1">02-文章大纲与目录组件 <a class="header-anchor" href="#_02-文章大纲与目录组件" aria-label="Permalink to &quot;02-文章大纲与目录组件&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1512486130939-2c4f79935e4f?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>右侧目录组件 <code>PostToc.vue</code> 作为阅读长文时的雷达导引，承载着章节概览、视口锚定与实时阅读进度反馈的重要职责。</p><h2 id="_1-大纲标题层级捕获与过滤" tabindex="-1">1. 大纲标题层级捕获与过滤 <a class="header-anchor" href="#_1-大纲标题层级捕获与过滤" aria-label="Permalink to &quot;1. 大纲标题层级捕获与过滤&quot;">​</a></h2><p>组件在页面完成初次渲染或路由切换后，动态扫描文章正文区域内的标题节点：</p><ul><li><strong>深度范围聚焦</strong>：严格抓取二级与三级标题，配合全站扁平化三级体系，确保大纲精炼不发散。</li><li><strong>重复主标题过滤</strong>：若正文首部的一级标题与文章元数据 title 一致，大纲组件会自动跳过该一级标题的生成，避免顶部重复罗列文档大标题。</li><li><strong>唯一锚点自动生成</strong>：系统将标题纯文本转化为标准可跳转的哈希锚点，支持包含中文、英文与数字的自然语义锚点。</li></ul><h2 id="_2-视口滚动高亮与精准定位" tabindex="-1">2. 视口滚动高亮与精准定位 <a class="header-anchor" href="#_2-视口滚动高亮与精准定位" aria-label="Permalink to &quot;2. 视口滚动高亮与精准定位&quot;">​</a></h2><p>如何在大篇幅长文中准确判定读者眼前正在阅读哪一个小节，是目录组件的核心算法难点：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>浏览器视口顶部</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├── 顶部偏移缓冲区 (Top Offset Buffer, 避开固定导航栏)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼  正文滚动监听线 (基于视口高度比例计算)</span></span>
<span class="line"><span>当前激活章节标题 ────► 右侧大纲对应项高亮并显示进度小圆点</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └── 页面平滑推进</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>节流滚动监听</strong>：采用高效的节流处理函数对窗口滚动事件进行侦听，每隔数十毫秒对比各标题相对于视口顶部的绝对距离，消除持续滚动带来的性能损耗。</li><li><strong>锚定当前阅读区域</strong>：动态计算位于视口上三分之一分割线以上的最后一个标题节点，将其判定为当前活跃章节，并在右侧大纲中同步点亮。</li><li><strong>平滑阻尼跳转</strong>：点击大纲某项时，阻止默认瞬间闪跳，触发浏览器的平滑滚动行为，精准滑翔至目标章节正文位置。</li></ul><h2 id="_3-视觉样式与暗色模式适配" tabindex="-1">3. 视觉样式与暗色模式适配 <a class="header-anchor" href="#_3-视觉样式与暗色模式适配" aria-label="Permalink to &quot;3. 视觉样式与暗色模式适配&quot;">​</a></h2><p>右侧大纲在排版上维持极简与克制：</p><ul><li><strong>层级缩进基准</strong>：二级标题靠左对齐，三级标题拥有固定的缩进深度，字号与行间距均保持适度紧凑。</li><li><strong>左侧轨道指示线</strong>：大纲整体左侧配有贯穿的细长轨道线，激活的章节项不仅字体变为主题强调色，其左侧指示小滑块亦会平滑滑动至对应行，提供沉浸式的阅读反馈。</li></ul>`,13)])])}const _=a(t,[["render",o]]);export{h as __pageData,_ as default};
